Method.Source:
/// <summary>
/// Calculates markupTrans value based on provided input parameters
/// ER seems to have problems to get current record from record list
/// </summary>
/// <param name = "_markupTransRecId">MarkupTrans RecId</param>
/// <param name = "_qty">Qty</param>
/// <param name = "_amount">total amount</param>
/// <param name = "_amountIC">intercompany amount</param>
/// <param name = "_isInclTax">boolean</param>
/// <returns>MarkupAmount</returns>
public static MarkupAmount markupTransCalcAmount(
    RefRecId _markupTransRecId, 
    Qty _qty, 
    AmountCur _amount, 
    AmountCur _amountIC, 
    boolean _isInclTax)
{
    MarkupTrans markupTrans;
    MarkupAmount calcAmount;

    select firstonly markupTrans
        where markupTrans.RecId == _markupTransRecId;

    calcAmount = Markup::calcMarkupAmount(markupTrans, _qty, _amount, _amountIC, _isInclTax);

    return calcAmount;
}
